# per-request steering vectors, see STEERING.md
#
# uses the random Gemma 4 model generated by test-llama-archs (ctest fixture), it has a dummy tokenizer so the
# prompts are token ids. override with LLAMA_STEERING_TEST_MODEL
import hashlib
import os

import numpy as np
import pytest
from utils import *

import gguf

MODEL = os.environ.get("LLAMA_STEERING_TEST_MODEL",
    os.path.join(os.path.dirname(__file__), "../../../../build/tests/test-models/gemma4-dense.gguf"))

pytestmark = pytest.mark.skipif(not os.path.exists(MODEL), reason=f"model not found: {MODEL} (run ctest -R test-generate-models)")

N_PREDICT = 16
PROMPT_A = [3, 17, 42, 9, 77, 5, 101, 23, 64, 8, 31, 12]
PROMPT_B = [55, 2, 90, 14, 6, 120, 33, 71, 19]

server: ServerProcess
vectors: dict[str, str] = {}


def model_shape(path: str) -> tuple[int, int]:
    reader = gguf.GGUFReader(path)
    arch = bytes(reader.fields["general.architecture"].parts[-1]).decode()
    n_embd  = int(reader.fields[f"{arch}.embedding_length"].parts[-1][0])
    n_layer = int(reader.fields[f"{arch}.block_count"].parts[-1][0])
    return n_embd, n_layer


def write_vector(path: str, seed: int, scale: float) -> str:
    n_embd, n_layer = model_shape(MODEL)
    rng = np.random.default_rng(seed)
    writer = gguf.GGUFWriter(path, "controlvector")
    writer.add_string("controlvector.model_hint", "gemma4")
    writer.add_uint32("controlvector.layer_count", n_layer)
    for il in range(1, n_layer):
        writer.add_tensor(f"direction.{il}", (rng.standard_normal(n_embd)*scale).astype(np.float32))
    writer.write_header_to_file()
    writer.write_kv_data_to_file()
    writer.write_tensors_to_file()
    writer.close()
    with open(path, "rb") as f:
        return hashlib.sha256(f.read()).hexdigest()


@pytest.fixture(scope="module", autouse=True)
def make_vectors(tmp_path_factory):
    d = tmp_path_factory.mktemp("steering")
    for name, seed in [("hunger", 1), ("sleep", 2), ("extra", 3)]:
        path = str(d / f"{name}.gguf")
        vectors[name] = path
        vectors[name + ":hash"] = write_vector(path, seed, 1.0)


def make_server(steering: bool = True) -> ServerProcess:
    s = ServerProcess()
    s.swa_full = True # otherwise the SWA cache of Gemma 4 limits the prompt reuse that the cache tests look at
    s.model_hf_repo = None
    s.model_file = MODEL
    s.n_ctx = 1024
    s.n_batch = 64
    s.n_slots = 2
    s.n_predict = N_PREDICT
    s.temperature = 0.0
    s.no_ui = True
    if steering:
        s.steering_vectors = [f"{n}={vectors[n]}" for n in ("hunger", "sleep")]
    return s


@pytest.fixture(autouse=True)
def create_server():
    global server
    server = make_server()
    yield
    server.stop()


# note: reusing a cached prompt re-evaluates its last token in a different ubatch than a cold prefill, which changes
# the logits by ~1e-5 even without steering. the exact comparisons therefore disable the prompt cache, the tests
# about the cache compare the tokens exactly and the logprobs with a tolerance far below the effect of steering
def complete(prompt, steering=None, id_slot=-1, cache_prompt=False):
    data = {
        "prompt": prompt,
        "n_predict": N_PREDICT,
        "temperature": 0.0,
        "n_probs": 4,
        "id_slot": id_slot,
        "cache_prompt": cache_prompt,
        "return_tokens": True,
    }
    if steering is not None:
        data["steering"] = steering
    res = server.make_request("POST", "/completion", data=data)
    assert res.status_code == 200, res.body
    return res.body


def result(body):
    return body["tokens"], body["completion_probabilities"]


def logprobs(body):
    return np.array([p["logprob"] for p in body["completion_probabilities"]])


def assert_close(hot, cold, effect):
    # same tokens, logprobs within a tolerance much smaller than the effect of steering
    assert hot["tokens"] == cold["tokens"]
    diff = np.abs(logprobs(hot) - logprobs(cold)).max()
    assert diff < 1e-3, diff
    assert effect > 10*1e-3, effect


def test_no_steering_matches_stock():
    global server
    server.stop()
    server = make_server(steering=False)
    server.start()
    ref = result(complete(PROMPT_A))
    server.stop()

    server = make_server()
    server.start()
    body = complete(PROMPT_A)
    assert result(body) == ref
    assert "steering" not in body
    # all scales zero: same output, the echo lists the vectors
    body = complete(PROMPT_A, {"hunger": 0.0})
    assert result(body) == ref
    assert body["steering"] == {"hunger": {"scale": 0.0, "hash": vectors["hunger:hash"]}}


def test_unknown_vector():
    server.start()
    res = server.make_request("POST", "/completion", data={"prompt": PROMPT_A, "steering": {"thirst": 1.0}})
    assert res.status_code == 400
    assert "thirst" in res.body["error"]["message"]
    res = server.make_request("POST", "/completion", data={"prompt": PROMPT_A, "steering": {"hunger": "a lot"}})
    assert res.status_code == 400


def test_not_enabled():
    global server
    server.stop()
    server = make_server(steering=False)
    server.start()
    res = server.make_request("POST", "/completion", data={"prompt": PROMPT_A, "steering": {"hunger": 1.0}})
    assert res.status_code == 400


def test_concurrent_requests_get_their_own_steering():
    server.start()
    sa = {"hunger": 0.6, "sleep": 0.2}
    sb = {"sleep": 1.5}

    # alone
    ref_a  = complete(PROMPT_A, sa)
    ref_b  = complete(PROMPT_B, sb)
    ref_a0 = complete(PROMPT_A)
    effect = np.abs(logprobs(ref_a) - logprobs(ref_a0)).max()

    # note: batched with other sequences, the logits change by ~1e-4 even without steering (batch composition)

    # concurrently, several rounds so that the slots and the batch composition change
    for _ in range(2):
        results = parallel_function_calls([
            (complete, (PROMPT_A, sa)),
            (complete, (PROMPT_B, sb)),
            (complete, (PROMPT_A, None)),
        ])
        assert_close(results[0], ref_a,  effect)
        assert_close(results[1], ref_b,  effect)
        assert_close(results[2], ref_a0, effect)
        assert results[0]["steering"] == {
            "hunger": {"scale": pytest.approx(0.6), "hash": vectors["hunger:hash"]},
            "sleep":  {"scale": pytest.approx(0.2), "hash": vectors["sleep:hash"]},
        }
        assert results[1]["steering"] == {"sleep": {"scale": pytest.approx(1.5), "hash": vectors["sleep:hash"]}}
        assert "steering" not in results[2]


def test_steered_reply_is_not_reused_from_cache():
    global server
    server.start()
    # steered request A, then an unsteered request whose prompt continues A with its reply, on the same slot
    body = complete(PROMPT_A, {"hunger": 4.0}, id_slot=0, cache_prompt=True)
    prompt_b = PROMPT_A + body["tokens"]
    hot = complete(prompt_b, id_slot=0, cache_prompt=True)
    # only the prompt of A is reused, the steered reply is evaluated again
    assert hot["timings"]["cache_n"] <= len(PROMPT_A)
    steered = complete(prompt_b, {"hunger": 4.0}, id_slot=1)
    server.stop()

    # the same request on a cold server
    server = make_server()
    server.start()
    cold = complete(prompt_b, id_slot=0)
    assert_close(hot, cold, np.abs(logprobs(steered) - logprobs(cold)).max())


def test_prompt_cache_reuse_with_different_steering():
    server.start()
    # the prompt is never steered: reusing its cache across different steering gives the same result as cold
    ref = complete(PROMPT_A, {"sleep": 1.0}, id_slot=1)
    other = complete(PROMPT_A, {"hunger": 2.0}, id_slot=1, cache_prompt=True)
    again = complete(PROMPT_A, {"sleep": 1.0}, id_slot=1, cache_prompt=True)
    assert again["timings"]["cache_n"] > 0
    assert_close(again, ref, np.abs(logprobs(other) - logprobs(ref)).max())


def test_stream_and_oai_echo():
    server.start()
    steering = {"hunger": 0.5}
    expected = {"hunger": {"scale": 0.5, "hash": vectors["hunger:hash"]}}

    chunks = list(server.make_stream_request("POST", "/completion", data={
        "prompt": PROMPT_A, "n_predict": 4, "steering": steering, "stream": True,
    }))
    assert chunks[-1]["stop"]
    assert chunks[-1]["steering"] == expected
    assert all("steering" not in c for c in chunks[:-1])

    res = server.make_request("POST", "/v1/completions", data={
        "prompt": PROMPT_A, "max_tokens": 4, "steering": steering,
    })
    assert res.status_code == 200
    assert res.body["steering"] == expected

    chunks = list(server.make_stream_request("POST", "/v1/completions", data={
        "prompt": PROMPT_A, "max_tokens": 4, "steering": steering, "stream": True,
    }))
    assert chunks[-1]["steering"] == expected


def test_register_at_runtime():
    server.start()
    res = server.make_request("GET", "/steering-vectors")
    assert res.status_code == 200
    assert res.body["enabled"]
    assert {v["name"]: v["hash"] for v in res.body["vectors"]} == {
        "hunger": vectors["hunger:hash"], "sleep": vectors["sleep:hash"],
    }

    res = server.make_request("POST", "/completion", data={"prompt": PROMPT_A, "steering": {"extra": 1.0}})
    assert res.status_code == 400

    res = server.make_request("POST", "/steering-vectors", data={"name": "extra", "path": vectors["extra"]})
    assert res.status_code == 200
    assert res.body["hash"] == vectors["extra:hash"]
    assert not res.body["replaced"]

    body = complete(PROMPT_A, {"extra": 1.0})
    assert body["steering"] == {"extra": {"scale": 1.0, "hash": vectors["extra:hash"]}}

    res = server.make_request("POST", "/steering-vectors", data={"name": "bad", "path": "/nonexistent.gguf"})
    assert res.status_code == 400


def test_chat_completion_echo():
    server.start()
    steering = {"sleep": 0.7}
    expected = {"sleep": {"scale": pytest.approx(0.7), "hash": vectors["sleep:hash"]}}
    messages = [{"role": "user", "content": "hi"}]

    res = server.make_request("POST", "/v1/chat/completions", data={
        "messages": messages, "max_tokens": 4, "steering": steering,
    })
    assert res.status_code == 200, res.body
    assert res.body["steering"] == expected

    chunks = list(server.make_stream_request("POST", "/v1/chat/completions", data={
        "messages": messages, "max_tokens": 4, "steering": steering, "stream": True,
    }))
    assert chunks[-1]["steering"] == expected
    assert all("steering" not in c for c in chunks[:-1])

    res = server.make_request("POST", "/v1/chat/completions", data={
        "messages": messages, "max_tokens": 4, "steering": {"thirst": 1.0},
    })
    assert res.status_code == 400
